import numpy as np, tifffile, pandas as pd, glob, os
from cellpose import models
from skimage.measure import regionprops

model = models.CellposeModel(gpu=False, model_type='nuclei')
dark = tifffile.imread('/task/input/flatfield/dark.tif').astype(float)
flat1 = tifffile.imread('/task/input/flatfield/flat_ch1.tif').astype(float)
gain1 = (flat1 - dark) / np.mean(flat1 - dark)

annotations = {}
for f in sorted(glob.glob('/task/input/annotations/*.tsv')):
    w = os.path.basename(f).replace('.tsv', '')
    annotations[w] = pd.read_csv(f, sep='\t')

images = {}
for w in annotations:
    ch1 = tifffile.imread(f'/task/input/images/{w}_ch1.tif').astype(float)
    ch1_corr = (ch1 - dark) / gain1
    p1, p99 = np.percentile(ch1_corr, 1), np.percentile(ch1_corr, 99.5)
    norm = np.clip((ch1_corr - p1) / (p99 - p1 + 1e-5), 0, 1)
    images[w] = norm

def eval_params(diam, flow_th, cellprob_th):
    results = {}
    all_pass = True
    for w, df in annotations.items():
        masks, flows, styles = model.eval(images[w], diameter=diam, channels=[0, 0], 
                                          flow_threshold=flow_th, cellprob_threshold=cellprob_th)
        valid = 0
        for p in regionprops(masks):
            if p.bbox[2] >= 320 or p.bbox[3] >= 320:
                continue
            if p.minor_axis_length < 6.5:
                continue
            valid += 1
        manual = len(df)
        tol = max(3, 0.1 * manual)
        diff = abs(valid - manual)
        passed = diff <= tol
        if not passed:
            all_pass = False
        results[w] = (manual, valid, diff, tol, passed)
    return all_pass, results

for diam in [13.0, 14.0, 15.0]:
    for flow_th in [0.4, 0.6]:
        for cellprob_th in [0.0, -0.5, -1.0]:
            passed, res = eval_params(diam, flow_th, cellprob_th)
            tot_diff = sum(r[2] for r in res.values())
            print(f'diam={diam}, flow={flow_th}, prob={cellprob_th} -> all_pass={passed}, tot_diff={tot_diff:.1f}')
            for w, r in res.items():
                print(f'   {w}: man={r[0]}, pipe={r[1]}, diff={r[2]:.1f}, tol={r[3]:.1f}, pass={r[4]}')
            if passed:
                print('SUCCESS! Found passing parameters!')
                exit(0)
EOF
python3 test_cellpose_tune.py

