import numpy as np, tifffile, pandas as pd, glob, os
from skimage.feature import blob_dog

dark = tifffile.imread('/task/input/flatfield/dark.tif').astype(float)
flat1 = tifffile.imread('/task/input/flatfield/flat_ch1.tif').astype(float)
gain1 = (flat1 - dark) / np.mean(flat1 - dark)

annotations = {}
for f in sorted(glob.glob('/task/input/annotations/*.tsv')):
    w = os.path.basename(f).replace('.tsv', '')
    annotations[w] = pd.read_csv(f, sep='\t')

images = {}
for w in annotations:
    ch1 = tifffile.imread(f'/task/input/images/{w}_ch1.tif').astype(float)
    images[w] = (ch1 - dark) / gain1

for min_sigma in [3, 4, 5]:
    for max_sigma in [8, 10, 12]:
        for thresh in [0.05, 0.1, 0.15, 0.2]:
            all_pass = True
            res = {}
            for w, df in annotations.items():
                im = images[w]
                p1, p99 = np.percentile(im, 1), np.percentile(im, 99.5)
                norm = np.clip((im - p1) / (p99 - p1 + 1e-5), 0, 1)
                blobs = blob_dog(norm, min_sigma=min_sigma, max_sigma=max_sigma, threshold=thresh)
                count = 0
                for b in blobs:
                    y, x, r = b[0], b[1], np.sqrt(2)*b[2]
                    if y + r >= 320 or x + r >= 320:
                        continue
                    count += 1
                man = len(df)
                tol = max(3, 0.1 * man)
                diff = abs(count - man)
                if diff > tol:
                    all_pass = False
                res[w] = (man, count, diff, tol)
            if all_pass:
                print(f'PASS! min_s={min_sigma}, max_s={max_sigma}, th={thresh}')
                for w, r in res.items():
                    print(f'  {w}: man={r[0]}, pipe={r[1]}, diff={r[2]:.1f}, tol={r[3]:.1f}')
                break
        if all_pass: break
    if all_pass: break
